-- PLEASE / CAL — STEP 18.9 Advanced Period Close verification (read-only)
with checks as (
select 1 n,'period_close_tables' check_name,case when to_regclass('public.accounting_period_close_checklist') is not null and to_regclass('public.accounting_period_close_snapshots') is not null and to_regclass('public.accounting_period_close_actions') is not null and to_regclass('public.accounting_period_adjustments') is not null then 'PASS' else 'FAIL' end status,'Advanced period-close control, snapshot, action and adjustment tables exist' detail
union all select 2,'fiscal_period_close_columns',case when (select count(*) from information_schema.columns where table_schema='public' and table_name='accounting_fiscal_periods' and column_name in ('close_state','close_version','last_prepared_at','last_prepared_by','close_notes','reopened_at','reopened_by','reopen_reason'))=8 then 'PASS' else 'FAIL' end,'Fiscal periods carry close/reopen workflow metadata'
union all select 3,'period_assert_open_rpc',case when to_regprocedure('public.accounting_assert_period_open(date,text)') is not null then 'PASS' else 'FAIL' end,'Central closed-period assertion RPC exists'
union all select 4,'event_effective_date_rpc',case when to_regprocedure('public.accounting_event_effective_date(text,text,text,jsonb,timestamptz)') is not null then 'PASS' else 'FAIL' end,'Financial event accounting-date resolver exists'
union all select 5,'enqueue_period_guard',case when position('accounting_assert_period_open' in pg_get_functiondef('public.accounting_enqueue_event(text,text,text,text,jsonb,timestamptz,integer,text,text,text)'::regprocedure))>0 and position('POSTED' in pg_get_functiondef('public.accounting_enqueue_event(text,text,text,text,jsonb,timestamptz,integer,text,text,text)'::regprocedure))>0 then 'PASS' else 'FAIL' end,'Durable event enqueue blocks new/unposted events in closed periods but preserves idempotent posted events'
union all select 6,'journal_lock_trigger',case when exists(select 1 from pg_trigger where tgname='trg_accounting_validate_posted_journal' and not tgisinternal) then 'PASS' else 'FAIL' end,'Final journal posting remains protected by the period-lock trigger'
union all select 7,'prepare_period_rpc',case when to_regprocedure('public.accounting_prepare_period_close(date,date,text)') is not null then 'PASS' else 'FAIL' end,'Prepare/refresh period workflow RPC exists'
union all select 8,'refresh_checklist_rpc',case when to_regprocedure('public.accounting_refresh_period_close_checklist(uuid,text)') is not null then 'PASS' else 'FAIL' end,'Automated period-close checklist refresh RPC exists'
union all select 9,'override_control_rpc',case when to_regprocedure('public.accounting_override_period_close_control(uuid,text,text,text)') is not null then 'PASS' else 'FAIL' end,'Review control sign-off/override RPC exists'
union all select 10,'close_period_rpc',case when to_regprocedure('public.accounting_close_fiscal_period(uuid,text,text)') is not null then 'PASS' else 'FAIL' end,'Controlled close RPC exists'
union all select 11,'reopen_period_rpc',case when to_regprocedure('public.accounting_reopen_fiscal_period(uuid,text,text)') is not null then 'PASS' else 'FAIL' end,'Reason-controlled reopen RPC exists'
union all select 12,'period_adjustment_rpc',case when to_regprocedure('public.accounting_create_period_close_adjustment(uuid,date,text,jsonb,text,text)') is not null then 'PASS' else 'FAIL' end,'Period-close adjusting-entry source-event RPC exists'
union all select 13,'period_reversal_rpc',case when to_regprocedure('public.accounting_create_period_close_reversal(uuid,date,text,text)') is not null then 'PASS' else 'FAIL' end,'Controlled next-period reversal RPC exists'
union all select 14,'historical_inventory_control',case when to_regprocedure('public.accounting_inventory_subledger_value_as_of(date)') is not null then 'PASS' else 'FAIL' end,'Inventory subledger can be reconciled as of period end'
union all select 15,'historical_fixed_asset_controls',case when to_regprocedure('public.accounting_fixed_asset_gross_subledger_value_as_of(date)') is not null and to_regprocedure('public.accounting_fixed_asset_accum_subledger_value_as_of(date)') is not null then 'PASS' else 'FAIL' end,'Fixed-asset subledger can be reconciled as of period end'
union all select 16,'close_tables_rls',case when (select count(*) from pg_class where oid in ('public.accounting_period_close_checklist'::regclass,'public.accounting_period_close_snapshots'::regclass,'public.accounting_period_close_actions'::regclass,'public.accounting_period_adjustments'::regclass) and relrowsecurity)=4 then 'PASS' else 'FAIL' end,'All period-close evidence tables are protected by RLS'
union all select 17,'close_evidence_immutability',case when exists(select 1 from pg_trigger where tgname='trg_accounting_period_close_snapshots_immutable' and not tgisinternal) and exists(select 1 from pg_trigger where tgname='trg_accounting_period_close_actions_immutable' and not tgisinternal) and exists(select 1 from pg_trigger where tgname='trg_accounting_period_adjustments_immutable' and not tgisinternal) then 'PASS' else 'FAIL' end,'Snapshots, close actions and posted adjustments are immutable'
union all select 18,'adjustment_reversal_uniqueness',case when exists(select 1 from pg_indexes where schemaname='public' and indexname='accounting_period_adjustments_reversal_uq') then 'PASS' else 'FAIL' end,'An adjustment can have at most one controlled reversal'
union all select 19,'adjustment_sequence_privilege',case when has_sequence_privilege('service_role','public.accounting_period_adjustment_number_seq','USAGE') then 'PASS' else 'FAIL' end,'Service role can generate adjustment numbers'
union all select 20,'hard_control_seed_logic',case when position('ENGINE_QUEUE' in pg_get_functiondef('public.accounting_refresh_period_close_checklist(uuid,text)'::regprocedure))>0 and position('TRIAL_BALANCE' in pg_get_functiondef('public.accounting_refresh_period_close_checklist(uuid,text)'::regprocedure))>0 and position('INVENTORY_RECON' in pg_get_functiondef('public.accounting_refresh_period_close_checklist(uuid,text)'::regprocedure))>0 and position('FIXED_ASSET_RECON' in pg_get_functiondef('public.accounting_refresh_period_close_checklist(uuid,text)'::regprocedure))>0 then 'PASS' else 'FAIL' end,'Hard engine/ledger/subledger controls are part of the checklist'
union all select 21,'review_control_seed_logic',case when position('BANK_RECON' in pg_get_functiondef('public.accounting_refresh_period_close_checklist(uuid,text)'::regprocedure))>0 and position('PAYROLL_CUTOFF' in pg_get_functiondef('public.accounting_refresh_period_close_checklist(uuid,text)'::regprocedure))>0 and position('GST_REVIEW' in pg_get_functiondef('public.accounting_refresh_period_close_checklist(uuid,text)'::regprocedure))>0 and position('DOCUMENT_EXCEPTIONS' in pg_get_functiondef('public.accounting_refresh_period_close_checklist(uuid,text)'::regprocedure))>0 then 'PASS' else 'FAIL' end,'Bank, payroll, tax and document review controls are part of the checklist'
union all select 22,'hard_controls_not_overridable',case when position('Hard controls cannot be overridden' in pg_get_functiondef('public.accounting_override_period_close_control(uuid,text,text,text)'::regprocedure))>0 then 'PASS' else 'FAIL' end,'Hard blockers cannot be overridden'
union all select 23,'close_requires_all_controls',case when position('Hard period-close blockers remain' in pg_get_functiondef('public.accounting_close_fiscal_period(uuid,text,text)'::regprocedure))>0 and position('Review controls still require sign-off/override' in pg_get_functiondef('public.accounting_close_fiscal_period(uuid,text,text)'::regprocedure))>0 then 'PASS' else 'FAIL' end,'Close is blocked until hard controls pass and review controls are signed off'
union all select 24,'close_creates_period_lock',case when position('accounting_period_locks' in pg_get_functiondef('public.accounting_close_fiscal_period(uuid,text,text)'::regprocedure))>0 then 'PASS' else 'FAIL' end,'Closing creates a date-range posting lock'
union all select 25,'reopen_removes_lock',case when position('delete from public.accounting_period_locks' in lower(pg_get_functiondef('public.accounting_reopen_fiscal_period(uuid,text,text)'::regprocedure)))>0 then 'PASS' else 'FAIL' end,'Reopening removes the exact period lock'
union all select 26,'chronological_reopen_guard',case when position('Reopen later closed periods first' in pg_get_functiondef('public.accounting_reopen_fiscal_period(uuid,text,text)'::regprocedure))>0 then 'PASS' else 'FAIL' end,'Earlier periods cannot be reopened underneath later closed periods'
union all select 27,'period_lock_overlap_integrity',case when not exists(select 1 from public.accounting_period_locks a join public.accounting_period_locks b on a.id<b.id and a.period_start<=b.period_end and a.period_end>=b.period_start) then 'PASS' else 'FAIL' end,'Existing period locks do not overlap'
union all select 28,'closed_period_lock_coverage',case when not exists(select 1 from public.accounting_fiscal_periods p where p.status='CLOSED' and not exists(select 1 from public.accounting_period_locks l where l.period_start=p.period_start and l.period_end=p.period_end)) then 'PASS' else 'FAIL' end,'Every closed fiscal period is covered by an exact period lock'
union all select 29,'close_evidence_version_uniqueness',case when not exists(select period_id,close_version from public.accounting_period_close_snapshots group by period_id,close_version having count(*)>1) then 'PASS' else 'FAIL' end,'Close snapshots are unique by period and close version'
union all select 30,'adjustment_balance_evidence',case when not exists(select 1 from public.accounting_period_adjustments a where round((select coalesce(sum((x->>'debit')::numeric),0) from jsonb_array_elements(a.lines_json) x),2)<>round((select coalesce(sum((x->>'credit')::numeric),0) from jsonb_array_elements(a.lines_json) x),2)) then 'PASS' else 'FAIL' end,'All stored period adjustments are balanced'
)
select n,check_name,status,detail from checks order by n;
